PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL UNIQUE, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, date_of_birth TEXT, account_status TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS profiles (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE, display_name TEXT, bio TEXT, avatar_id INTEGER, class_id INTEGER, title_id INTEGER, profile_visibility TEXT DEFAULT 'private', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS avatars (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, description TEXT, image_url TEXT, rarity TEXT, price INTEGER DEFAULT 0, currency_type TEXT DEFAULT 'gold', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS classes (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, description TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS titles (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, description TEXT, required_level INTEGER DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE IF NOT EXISTS goals (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, title TEXT NOT NULL, description TEXT, category TEXT, target_value REAL, current_value REAL DEFAULT 0, unit TEXT, deadline TEXT, status TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at TEXT);
CREATE TABLE IF NOT EXISTS assessments (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, goal_id INTEGER REFERENCES goals(id) ON DELETE SET NULL, assessment_type TEXT NOT NULL DEFAULT 'advisor', status TEXT NOT NULL DEFAULT 'in_progress', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at TEXT);
CREATE TABLE IF NOT EXISTS assessment_questions (id INTEGER PRIMARY KEY AUTOINCREMENT, assessment_id INTEGER NOT NULL REFERENCES assessments(id) ON DELETE CASCADE, question_text TEXT NOT NULL, question_type TEXT NOT NULL DEFAULT 'text', question_order INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(assessment_id, question_order));
CREATE TABLE IF NOT EXISTS assessment_answers (id INTEGER PRIMARY KEY AUTOINCREMENT, assessment_id INTEGER NOT NULL REFERENCES assessments(id) ON DELETE CASCADE, question_id INTEGER NOT NULL REFERENCES assessment_questions(id) ON DELETE CASCADE, answer TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(assessment_id, question_id));
CREATE TABLE IF NOT EXISTS ai_analyses (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, assessment_id INTEGER REFERENCES assessments(id), goal_id INTEGER NOT NULL REFERENCES goals(id) ON DELETE CASCADE, identified_problem TEXT, strengths TEXT, weaknesses TEXT, baseline_summary TEXT, recommended_strategy TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS advisor_blueprints (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, assessment_id INTEGER NOT NULL REFERENCES assessments(id), goal_id INTEGER NOT NULL REFERENCES goals(id) ON DELETE CASCADE, destination TEXT, success_definition TEXT, motivation TEXT, baseline TEXT, strengths TEXT, gaps TEXT, bottleneck TEXT, previous_experience TEXT, constraints TEXT, cut_list TEXT, first_objective TEXT, quest_strategy TEXT, status TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS path_stages (id INTEGER PRIMARY KEY AUTOINCREMENT, blueprint_id INTEGER NOT NULL REFERENCES advisor_blueprints(id) ON DELETE CASCADE, title TEXT NOT NULL, description TEXT, stage_order INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'locked', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at TEXT);
CREATE TABLE IF NOT EXISTS milestones (id INTEGER PRIMARY KEY AUTOINCREMENT, blueprint_id INTEGER NOT NULL REFERENCES advisor_blueprints(id) ON DELETE CASCADE, goal_id INTEGER NOT NULL REFERENCES goals(id) ON DELETE CASCADE, title TEXT NOT NULL, description TEXT, target_value REAL, unit TEXT, milestone_order INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'upcoming', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at TEXT);

CREATE TABLE IF NOT EXISTS stories (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, goal_id INTEGER NOT NULL REFERENCES goals(id) ON DELETE CASCADE, blueprint_id INTEGER REFERENCES advisor_blueprints(id), title TEXT NOT NULL, description TEXT, status TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at TEXT);
CREATE TABLE IF NOT EXISTS chapters (id INTEGER PRIMARY KEY AUTOINCREMENT, story_id INTEGER NOT NULL REFERENCES stories(id) ON DELETE CASCADE, title TEXT NOT NULL, description TEXT, chapter_order INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at TEXT);
CREATE TABLE IF NOT EXISTS objectives (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, type TEXT NOT NULL CHECK(type IN ('quest','mission')), chapter_id INTEGER REFERENCES chapters(id) ON DELETE SET NULL, path_stage_id INTEGER REFERENCES path_stages(id) ON DELETE SET NULL, milestone_id INTEGER REFERENCES milestones(id) ON DELETE SET NULL, title TEXT NOT NULL, description TEXT, difficulty TEXT, target_value REAL, current_value REAL DEFAULT 0, unit TEXT, xp_reward INTEGER DEFAULT 0, gold_reward INTEGER DEFAULT 0, status TEXT NOT NULL DEFAULT 'available', due_date TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at TEXT);
CREATE TABLE IF NOT EXISTS tasks (id INTEGER PRIMARY KEY AUTOINCREMENT, objective_id INTEGER NOT NULL REFERENCES objectives(id) ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, title TEXT NOT NULL, description TEXT, task_type TEXT, target_value REAL DEFAULT 1, current_value REAL DEFAULT 0, unit TEXT, task_order INTEGER NOT NULL DEFAULT 1, xp_reward INTEGER DEFAULT 0, gold_reward INTEGER DEFAULT 0, status TEXT NOT NULL DEFAULT 'available', due_date TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at TEXT);
CREATE TABLE IF NOT EXISTS task_completions (id INTEGER PRIMARY KEY AUTOINCREMENT, task_id INTEGER NOT NULL REFERENCES tasks(id) ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, actual_value REAL, notes TEXT, completed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS proof_submissions (id INTEGER PRIMARY KEY AUTOINCREMENT, task_id INTEGER NOT NULL REFERENCES tasks(id) ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, proof_type TEXT, file_url TEXT, description TEXT, status TEXT DEFAULT 'submitted', submitted_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS task_feedback (id INTEGER PRIMARY KEY AUTOINCREMENT, task_id INTEGER NOT NULL REFERENCES tasks(id) ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, difficulty INTEGER, confidence INTEGER, rating INTEGER, comment TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS measurements (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, goal_id INTEGER NOT NULL REFERENCES goals(id) ON DELETE CASCADE, milestone_id INTEGER REFERENCES milestones(id), task_id INTEGER REFERENCES tasks(id), metric TEXT NOT NULL, value REAL NOT NULL, unit TEXT, recorded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS boss_battles (id INTEGER PRIMARY KEY AUTOINCREMENT, objective_id INTEGER NOT NULL REFERENCES objectives(id) ON DELETE CASCADE, title TEXT NOT NULL, description TEXT, time_limit_seconds INTEGER, hp_penalty INTEGER DEFAULT 0, xp_reward INTEGER DEFAULT 0, gold_reward INTEGER DEFAULT 0, status TEXT DEFAULT 'available', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS boss_battle_attempts (id INTEGER PRIMARY KEY AUTOINCREMENT, boss_battle_id INTEGER NOT NULL REFERENCES boss_battles(id) ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, started_at TEXT, completed_at TEXT, status TEXT DEFAULT 'active', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE IF NOT EXISTS player_progress (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE, current_xp INTEGER NOT NULL DEFAULT 0, current_level INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS levels (id INTEGER PRIMARY KEY AUTOINCREMENT, level INTEGER NOT NULL UNIQUE, xp_required INTEGER NOT NULL, growth_points_reward INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS xp_transactions (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, amount INTEGER NOT NULL, source_type TEXT, source_id INTEGER, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS player_wallet (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE, gold INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS gold_transactions (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, amount INTEGER NOT NULL, transaction_type TEXT, source_type TEXT, source_id INTEGER, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS user_stats (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE, mind INTEGER NOT NULL DEFAULT 0, body INTEGER NOT NULL DEFAULT 0, will INTEGER NOT NULL DEFAULT 0, spirit INTEGER NOT NULL DEFAULT 0, influence INTEGER NOT NULL DEFAULT 0, growth_points INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS stat_transactions (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, stat_type TEXT, amount INTEGER NOT NULL, source_type TEXT, source_id INTEGER, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS player_resources (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE, current_hp INTEGER NOT NULL DEFAULT 100, max_hp INTEGER NOT NULL DEFAULT 100, current_mp INTEGER NOT NULL DEFAULT 100, max_mp INTEGER NOT NULL DEFAULT 100, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS hp_transactions (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, amount INTEGER NOT NULL, source_type TEXT, source_id INTEGER, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE IF NOT EXISTS abilities (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, description TEXT, mp_cost INTEGER DEFAULT 0, cooldown_seconds INTEGER DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ability_effects (id INTEGER PRIMARY KEY AUTOINCREMENT, ability_id INTEGER NOT NULL REFERENCES abilities(id) ON DELETE CASCADE, effect_type TEXT, multiplier REAL, flat_amount REAL, duration_type TEXT, duration_value INTEGER, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS user_abilities (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, ability_id INTEGER NOT NULL REFERENCES abilities(id), unlocked INTEGER NOT NULL DEFAULT 0, ability_level INTEGER NOT NULL DEFAULT 1, unlocked_at TEXT, UNIQUE(user_id, ability_id));
CREATE TABLE IF NOT EXISTS active_abilities (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, ability_id INTEGER NOT NULL REFERENCES abilities(id), activated_at TEXT, expires_at TEXT, remaining_uses INTEGER, cooldown_until TEXT, status TEXT DEFAULT 'active', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS shop_items (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, description TEXT, item_type TEXT, price INTEGER DEFAULT 0, currency_type TEXT DEFAULT 'gold', rarity TEXT, stock INTEGER, status TEXT DEFAULT 'active', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS user_inventory (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, item_id INTEGER NOT NULL REFERENCES shop_items(id), quantity INTEGER NOT NULL DEFAULT 0, purchased_at TEXT, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id, item_id));
CREATE TABLE IF NOT EXISTS item_effects (id INTEGER PRIMARY KEY AUTOINCREMENT, item_id INTEGER NOT NULL REFERENCES shop_items(id) ON DELETE CASCADE, effect_type TEXT, multiplier REAL, flat_amount REAL, duration_type TEXT, duration_value INTEGER, cooldown_seconds INTEGER, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS active_item_effects (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, item_id INTEGER NOT NULL REFERENCES shop_items(id), activated_at TEXT, expires_at TEXT, remaining_uses INTEGER, cooldown_until TEXT, status TEXT DEFAULT 'active', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS item_usage (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, item_id INTEGER NOT NULL REFERENCES shop_items(id), quantity_used INTEGER NOT NULL, source_type TEXT, source_id INTEGER, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS streaks (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, streak_type TEXT NOT NULL, current_streak INTEGER DEFAULT 0, longest_streak INTEGER DEFAULT 0, last_completed_date TEXT, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id, streak_type));
CREATE TABLE IF NOT EXISTS conversations (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, conversation_type TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS messages (id INTEGER PRIMARY KEY AUTOINCREMENT, conversation_id INTEGER NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, role TEXT NOT NULL, content TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notifications (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, type TEXT, title TEXT, message TEXT, is_read INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE INDEX IF NOT EXISTS idx_goals_user_status ON goals(user_id, status);
CREATE INDEX IF NOT EXISTS idx_objectives_user_status ON objectives(user_id, status);
CREATE INDEX IF NOT EXISTS idx_tasks_user_status ON tasks(user_id, status);
CREATE INDEX IF NOT EXISTS idx_measurements_goal ON measurements(goal_id, recorded_at);
